f=(x,y,n=0)=>
  x<2
  ? f(x*x-y*y,2*tan(2*x*y)-1/2,n+1)
  : (cos(n/4)+1)*128

Y=0
setup=()=>{
  createCanvas(w=windowWidth,h=windowHeight)
//  createCanvas(w=1920,h=1080)
}

draw=()=>{
  if(Y<h){
    for(X=w;X--;){
      x=map(X,0,w,-1,1)
      y=map(Y,0,h,-h/w,h/w)
      stroke(f(x,y))
      point(X,Y)
    }
    Y++
  }
}
